SZGame2D.onStart(function __szProjectRun() {
  const __szProjectRunContext = window.__SZProjectLifecycle.begin(() => SZGame2D.restart());
  // Ao iniciar
  SZGame2D.setupStage(640, 480, "#e9e4ff");
  SZGame2D.enableClassicControls("always");
  const guia = SZGame2D.createDino({ x: 48, y: 300, size: 56, color: "#f2b84b" });
  let temEstrela = false;
  let aceso = false;
  const estrela = SZGame2D.createSprite({ x: 260, y: 352, w: 48, h: 48, image: "estrela" });
  const farol = SZGame2D.createSprite({ x: 560, y: 352, w: 48, h: 48, image: "farol" });
  const pedras = SZGame2D.createGroup();
  // Quando acontecer
  SZGame2D.onOverlap(() => guia, () => estrela, () => {
    temEstrela = true;
    SZGame2D.destroySprite(estrela);
  }, "farol-meu-jogo_events_0");
  SZGame2D.onOverlap(() => guia, () => farol, () => {
    if (temEstrela) {
      aceso = true;
    }
  }, "farol-meu-jogo_events_1");
  SZGame2D.onKey("Enter", () => {
    SZGame2D.restart();
  }, "farol-meu-jogo_events_2");
  // Enquanto estiver rodando
  // O jogo roda 60 passos por segundo: cada volta desenha um "quadro" do filme.
  SZGame2D.gameLoop(function update() {
    SZGame2D.arrowsX(guia, 5);
    SZGame2D.applyGravity(guia);
    SZGame2D.controlDino(guia, ctx, 14);
    SZGame2D.clampToScreen(guia, ctx);
    SZGame2D.updateGroup(pedras);
    SZGame2D.overlapSpriteGroup(() => guia, pedras, (pedra) => {
      SZGame2D.explodeSprite(pedra, "#9a8f86");
    });
    SZGame2D.clear();
    SZGame2D.drawLabel(ctx, "Meu jogo do Arquipélago", 20, 35, "#2c2a4a", 18, "left");
    SZGame2D.drawGroup(ctx, pedras);
    SZGame2D.drawSprite(ctx, estrela);
    SZGame2D.drawSprite(ctx, farol);
    if (aceso) {
      SZGame2D.drawLabel(ctx, "O farol acendeu.", 20, 70, "#2c2a4a", 18, "left");
    }
    SZGame2D.drawSprite(ctx, guia);
  }, "farol-meu-jogo_loops_0");
  SZGame2D.gameLoop(function __szPeriodicLoop() {
    if (SZGame2D.everySeconds("cada", 2.5)) {
      SZGame2D.spawnObstacle(pedras, ctx, { type: "rock", x: SZGame2D.randomBetween(660, 760), size: 28, vx: -3 });
    }
  });
}, "__sz-project");
